// Research plan: which searches to run this time, and whether we need a new CJ token.
// Rules from the owner: Canada first, no electronics, no cosmetics. Kids/baby, food,
// supplements and medical items are also skipped (extra Canadian safety/import rules).
const CONFIG = {
  keywords: [
    'kitchen gadget', 'kitchen organizer', 'pet grooming', 'pet bowl', 'home storage',
    'closet organizer', 'bathroom accessories', 'car organizer', 'camping gear',
    'yoga accessories', 'garden tools', 'cleaning brush', 'desk organizer', 'travel accessories',
  ],
  per_run: 3,              // searches per run (CJ allows about 1 request per second)
  page_size: 50,           // CJ sorts by how many stores list each product (orderBy=listedNum)
};
const store = $getWorkflowStaticData('global');
const start = (store.kwIndex || 0) % CONFIG.keywords.length;
const picked = [0, 1, 2].slice(0, CONFIG.per_run).map(i => CONFIG.keywords[(start + i) % CONFIG.keywords.length]);
store.kwIndex = start + CONFIG.per_run;
// Owner can force keywords when calling this workflow from another one (Execute Workflow input).
const forced = ($input.first().json && $input.first().json.keywords) || null;
const keywords = Array.isArray(forced) && forced.length ? forced.slice(0, 5) : picked;
const t = store.cjToken;
const tokenOk = t && t.value && t.expires && new Date(t.expires).getTime() - Date.now() > 24 * 3600 * 1000;
return [{ json: { run_id: 'research_' + Date.now().toString(36), keywords, page_size: CONFIG.page_size,
                  need_token: !tokenOk, token: tokenOk ? t.value : null } }];

// Keep the CJ access token (valid about 15 days; CJ limits how often a new one can be requested).
const r = $input.first().json || {};
const d = r.data || {};
const value = d.accessToken || d.access_token || null;
if (!value) throw new Error('CJ did not return an access token: ' + JSON.stringify(r).slice(0, 300));
const expires = d.accessTokenExpiryDate || new Date(Date.now() + 14 * 24 * 3600 * 1000).toISOString();
const store = $getWorkflowStaticData('global');
store.cjToken = { value, expires };
const plan = $('Research plan').first().json;
return [{ json: { ...plan, need_token: false, token: value } }];

// One item per keyword -> one CJ product search each.
const plan = $input.first().json;
return plan.keywords.map(k => ({ json: { keyword: k, token: plan.token, page_size: plan.page_size, run_id: plan.run_id } }));

// Screen CJ search results (no AI): excluded categories, price band, de-duplicate, competition check, rank.
// Demand = how many stores already list the product on CJ (CJ returns results sorted by it), plus
// CJ's sales/order count when the API provides one. Keeps the best 8.
const EXCLUDE = /(spot ?light|flash ?light|\blights?\b|rechargeable|solar|glow|electr|usb|batter|charg|bluetooth|earphone|headphone|speaker|camera|phone|smart ?watch|\bled\b|lamp|cosmetic|make ?up|lipstick|mascara|skin ?care|serum|cream|perfume|nail polish|hair dye|toy|\bkid|child|baby|infant|toddler|food|snack|supplement|vitamin|medical|medicine|knife set|weapon|vape|e-cig|cbd|lithium)/i;
const MAX_COST_USD = 20;   // supplier price ceiling, before shipping
const searches = $('Searches').all().map(i => i.json);
const out = [], seen = new Set(), notes = [];
$input.all().forEach((item, idx) => {
  const r = item.json || {};
  if (r.error) { notes.push(`search "${searches[idx]?.keyword}": request failed (${(r.error.message || JSON.stringify(r.error)).slice(0, 120)})`); return; }
  if (r.result === false || (r.code && r.code !== 200)) { notes.push(`search "${searches[idx]?.keyword}": CJ said ${r.message || r.code}`); return; }
  const d = r.data || {};
  let list = d.list || d.content || [];
  if (list.length && list[0] && Array.isArray(list[0].productList)) list = list.flatMap(x => x.productList);
  for (const p of list) {
    const pid = p.pid || p.id; if (!pid || seen.has(pid)) continue;
    const name = p.productNameEn || p.nameEn || p.productName || '';
    const cat = p.categoryName || p.threeCategoryName || '';
    const price = parseFloat(String(p.sellPrice ?? p.nowPrice ?? '').split('-')[0]);
    if (!name || EXCLUDE.test(name + ' ' + cat) || !(price > 0) || price > MAX_COST_USD) continue;
    seen.add(pid);
    let image = p.productImage || p.bigImage || p.image || '';
    if (typeof image === 'string' && image.trim().startsWith('[')) { try { image = JSON.parse(image)[0] || ''; } catch { image = ''; } }
    if (Array.isArray(image)) image = image[0] || '';
    image = String(image || '').replace(/^http:/, 'https:');
    const sold = Number(p.saleNum ?? p.salesVolume ?? p.soldNum ?? p.orderNum ?? 0) || 0;
    out.push({ pid, name: name.slice(0, 120), category: cat, sku: p.productSku || p.sku || '',
               image: /^https:\/\//.test(image) ? image : '', list_price_usd: price,
               listed_by_stores: Number(p.listedNum ?? p.listedShopNum ?? 0) || 0, sold_count: sold,
               keyword: searches[idx]?.keyword || '', token: searches[0]?.token });
  }
});
const demand = x => x.listed_by_stores + 2 * x.sold_count;
out.forEach(x => { x.demand_score = demand(x); });

// Competition check (no AI). Two signals:
//  1. how many stores already sell it through CJ (more stores = proven, but also more competitors)
//  2. how many near-identical products came up in the same searches (copies of the same item)
// Bands: under 20 = unproven, 20-1999 = healthy (best), 2000-7999 = crowded, 8000+ = saturated.
const words = n => new Set(String(n).toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/)
  .filter(w => w.length > 3 && !['with', 'for', 'and', 'the', 'from', 'pet', 'dog', 'cat', 'home', 'kitchen', 'tool', 'tools'].includes(w)));
const W = out.map(x => words(x.name));
out.forEach((x, i) => {
  x.similar_count = W.filter((w, j) => j !== i && [...W[i]].filter(t => w.has(t)).length >= 3).length;
  const n = x.listed_by_stores;
  x.competition = n < 20 ? 'unproven' : n < 2000 ? 'healthy' : n < 8000 ? 'crowded' : 'saturated';
});
const BAND = { healthy: 0, crowded: 1, unproven: 2, saturated: 3 };
out.sort((a, b) => (BAND[a.competition] - BAND[b.competition]) || (a.similar_count >= 4) - (b.similar_count >= 4) || b.demand_score - a.demand_score);
const keep = out.slice(0, 10);
if (!keep.length) return [{ json: { empty: true, notes, token: searches[0]?.token } }];
return keep.map(p => ({ json: { ...p, screen_notes: notes } }));

// First sellable variant of each product: its id (needed for shipping), price and weight.
const prods = $('Screen products').all().map(i => i.json);
return $input.all().map((item, idx) => {
  const p = prods[idx]; const r = item.json || {};
  const vs = Array.isArray(r.data) ? r.data : (r.data && (r.data.variants || r.data.list)) || [];
  const v = vs.find(x => x && (x.vid || x.variantId)) || null;
  return { json: { ...p, vid: v ? (v.vid || v.variantId) : null,
                   variant_name: v ? (v.variantNameEn || v.variantName || '') : '',
                   cost_usd: v ? parseFloat(v.variantSellPrice ?? v.sellPrice ?? p.list_price_usd) || p.list_price_usd : p.list_price_usd,
                   weight_g: v ? Number(v.variantWeight ?? v.weight ?? 0) || null : null } };
});

// Finance 1 (pure arithmetic, no AI). Every number is an ESTIMATE from CJ's quoted prices.
const F = {
  usd_to_cad: 1.40,          // check the current rate before relying on results
  markup: 2.5,               // suggested retail = landed cost x markup, then rounded to .99
  min_profit_cad: 12,        // or at least this much above landed cost
  max_retail_cad: 60,        // owner's price ceiling
  payment_pct: 0.029, payment_fixed_cad: 0.30,   // card processing (verify on your Shopify plan)
  returns_pct: 0.05,         // allowance for refunds/returns
  marketing_pct: 0.20,       // allowance for ads/promotion per sale
  max_days: 20,              // longest acceptable delivery estimate to Canada
  // Owner's TARGETS (2026-11-10): products meeting both are listed first and marked 🎯
  target_profit_cad: 10,
  target_days: 10,
};
const prods = $('Pick variant').all().map(i => i.json);
const out = [];
$input.all().forEach((item, idx) => {
  const p = prods[idx]; const r = item.json || {};
  const opts = (Array.isArray(r.data) ? r.data : []).map(o => ({
    name: o.logisticName || o.name || '?', usd: parseFloat(o.logisticPrice ?? o.price), days: String(o.logisticAging || o.aging || '')
  })).filter(o => o.usd >= 0);
  const maxDays = o => { const n = (o.days.match(/\d+/g) || []).map(Number); return n.length ? Math.max(...n) : 99; };
  const ok = opts.filter(o => maxDays(o) <= F.max_days).sort((a, b) => a.usd - b.usd);
  const ship = ok[0] || opts.sort((a, b) => a.usd - b.usd)[0] || null;
  const landed_usd = p.cost_usd + (ship ? ship.usd : 0);
  const landed = +(landed_usd * F.usd_to_cad).toFixed(2);
  let price = Math.max(landed * F.markup, landed + F.min_profit_cad);
  price = Math.ceil(price) - 0.01;
  const fees = price * F.payment_pct + F.payment_fixed_cad;
  const profit = +(price - landed - fees - price * F.returns_pct - price * F.marketing_pct).toFixed(2);
  const flags = [];
  if (!p.vid) flags.push('no variant data');
  if (!ship) flags.push('no shipping quote to Canada');
  else if (maxDays(ship) > F.max_days) flags.push('slow delivery (' + ship.days + ' days)');
  if (price > F.max_retail_cad) flags.push('price above ' + F.max_retail_cad + ' CAD');
  if (profit < 8) flags.push('thin profit');
  if (p.competition === 'unproven') flags.push('unproven demand (few stores sell it yet)');
  if (p.competition === 'crowded') flags.push('crowded: ' + p.listed_by_stores + ' stores already sell it');
  if (p.competition === 'saturated') flags.push('saturated: ' + p.listed_by_stores + ' stores sell it, hard to stand out');
  if (p.similar_count >= 4) flags.push(p.similar_count + ' near-identical copies on CJ');
  const days = ship ? maxDays(ship) : 99;
  const meets_target = !!ship && profit >= F.target_profit_cad && days <= F.target_days;
  const misses = [];
  if (profit < F.target_profit_cad) misses.push('profit under ' + F.target_profit_cad + ' CAD');
  if (days > F.target_days) misses.push('delivery over ' + F.target_days + ' days');
  out.push({ json: { ...p, meets_target, target_misses: misses, shipping: ship, landed_cad: landed, price_cad: +price.toFixed(2),
                     est_profit_cad: profit, margin_pct: Math.round(profit / price * 100), flags,
                     estimate_note: 'Estimates from CJ quotes; excludes sales tax, duties and samples.' } });
});
return out;

// Rank: no blocking flags first, then products meeting the owner's targets, then competition band (healthy > crowded > unproven > saturated), then profit x demand. Top 5.
const all = $input.all().map(i => i.json);
const blocking = f => f.some(x => /no shipping|slow|above/.test(x));
const BAND = { healthy: 0, crowded: 1, unproven: 2, saturated: 3 };
all.sort((a, b) => (blocking(a.flags) - blocking(b.flags)) || (Number(!!b.meets_target) - Number(!!a.meets_target)) || (BAND[a.competition] - BAND[b.competition]) ||
                   (b.est_profit_cad * Math.log2(2 + b.demand_score) - a.est_profit_cad * Math.log2(2 + a.demand_score)));
const top = all.slice(0, 5);
const facts = top.map((p, i) => ({ n: i + 1, pid: p.pid, name: p.name, category: p.category, cost_usd: p.cost_usd,
  shipping: p.shipping, landed_cad: p.landed_cad, price_cad: p.price_cad, est_profit_cad: p.est_profit_cad,
  listed_by_stores: p.listed_by_stores, competition: p.competition, meets_targets: p.meets_target, similar_count: p.similar_count, sold_count: p.sold_count, flags: p.flags }));
const instructions = 'You are the JARVIS e-commerce research analyst for a new Shopify store selling in Canada. ' +
  'For each product below write one short note (max 25 words): who would buy it and the main risk. Use ONLY the facts given; ' +
  'do not invent sales numbers, trends, reviews or prices. Reply with JSON only: {"notes":[{"n":1,"note":"..."}]}';
return [{ json: { top, instructions, ai_body: { model: 'jarvis-free', max_tokens: 900, response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: instructions }, { role: 'user', content: JSON.stringify(facts) }] } } }];

// One photo message per product (caption = the facts), then a short summary message.
// Works with or without the AI notes and with or without images.
const s = $('Shortlist').first().json;
const plan = $('Research plan').first().json;
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let notes = {};
try {
  const r = $input.first().json || {};
  const txt = (r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content || '').replace(/^\s*```(?:json)?|```\s*$/g, '');
  for (const x of (JSON.parse(txt).notes || [])) notes[x.n] = x.note;
} catch (e) { /* AI notes are optional */ }
const items = s.top.map((p, i) => {
  const lines = [
    `<b>${i + 1}. ${esc(p.name)}</b>`,
    `${{ healthy: '🟢', crowded: '🟠', saturated: '🔴', unproven: '⚪' }[p.competition] || ''} Competition: ${p.competition} (${p.listed_by_stores} stores on CJ` +
      (p.similar_count ? `, ${p.similar_count} similar` : '') + ')' + (p.sold_count ? ` · ${p.sold_count} sold` : ''),
    `Cost ${p.cost_usd.toFixed(2)} USD + shipping ${p.shipping ? p.shipping.usd.toFixed(2) + ' USD (' + esc(p.shipping.name) + ', ' + esc(p.shipping.days) + ' days)' : 'unknown'}`,
    `Landed ~${p.landed_cad} CAD | price ${p.price_cad} CAD | est. profit ${p.est_profit_cad} CAD (${p.margin_pct}%)`,
    `CJ SKU ${esc(p.sku || p.pid)}`,
    p.meets_target ? '🎯 Meets your targets (10+ CAD profit, 10 days or less)' : '✖️ Misses target: ' + esc((p.target_misses || []).join(', ')),
  ];
  if (p.flags.length) lines.push('Watch: ' + esc(p.flags.join('; ')));
  if (notes[i + 1]) lines.push('<i>' + esc(notes[i + 1]) + '</i>');
  return { json: { photo: p.image || '', has_photo: !!p.image, caption: lines.join('\n').slice(0, 1000), text: lines.join('\n') } };
});
const summary = '<b>JARVIS product research</b> (' + esc(plan.keywords.join(', ')) + ')\n' +
  s.top.length + ' products above. 🎯 = meets your targets (10+ CAD profit, delivery 10 days or less), listed first; then by competition and profit.\n' +
  (s.top.some(p => p.meets_target) ? '' : 'No product met both targets this week.\n') +
  '🟢 healthy = proven but not overcrowded · 🟠 crowded · 🔴 saturated · ⚪ unproven\n' +
  'All money figures are estimates from CJ quotes (USD to CAD at 1.40), before sales tax and duties. Nothing was ordered or published.\n' +
  'Next step (not automatic yet): tell JARVIS which numbers interest you. Ordering samples will always ask for your approval first.';
return items.map((it, i) => ({ json: { ...it.json, summary, index: i } }));

// Nothing passed the screen: tell the owner why instead of staying silent.
const r = $input.first().json || {};
const plan = $('Research plan').first().json;
const why = (r.notes && r.notes.length) ? r.notes.join('; ') : 'no product passed the filters (price, excluded categories)';
return [{ json: { report: 'JARVIS product research (' + plan.keywords.join(', ') + '): no candidates this time. ' + why.replace(/[<>&]/g, ' ') } }];

// After the product photos (runs once): the summary, plus the full text of any product whose photo
// could not be sent (no image, or Telegram rejected it), so nothing is lost.
const reports = $('Report').all().map(i => i.json);
const results = $input.all().map(i => i.json || {});
const failed = reports.filter((r, i) => !results[i] || results[i].error || !r.has_photo);
let msg = reports.length ? reports[0].summary : '';
if (failed.length) msg = failed.map(r => r.text).join('\n\n') + '\n\n' + msg;
return [{ json: { report: msg.slice(0, 4000) } }];

// What JARVIS says out loud after the report (spoken by the free Piper voice on the server). Short, factual, and only about what really happened.
let top = [];
try { top = $('Shortlist').first().json.top || []; } catch (e) { top = []; }
const hNum = Number(new Date().toLocaleString('en-CA', { timeZone: 'America/Toronto', hour: '2-digit', hour12: false })) % 24;
const hour = ((hNum % 12) || 12) + (hNum < 12 ? ' AM' : ' PM');
const NAME = 'Zohrab';
const greet = hNum < 12 ? 'Good morning' : hNum < 18 ? 'Good afternoon' : 'Good evening';
let text;
if (top.length) {
  const hits = top.filter(p => p.meets_target).length;
  const best = [...top].sort((a, b) => b.est_profit_cad - a.est_profit_cad)[0];
  const shortName = best.name.split(/[-,|]/)[0].trim().split(/\s+/).slice(0, 6).join(' ');
  text = `${greet}, ${NAME}. It's ${hour}. I've just sent this week's product research to your Telegram: ${top.length} product${top.length === 1 ? '' : 's'}, with photos, shipping times to Canada and profit estimates. ` +
         `The highest estimated profit is about ${Math.round(best.est_profit_cad)} dollars per sale, on the ${shortName}. ` +
         (hits ? `${hits} of them meet${hits === 1 ? 's' : ''} your targets. ` : 'None met both of your targets this week. ') + `These are estimates only; nothing has been ordered. Have a look when you have a moment.`;
} else {
  text = `${greet}, ${NAME}. I ran this week's product research, but no product passed the filters this time. The details are in your Telegram.`;
}
return [{ json: { tts_body: { text: text.slice(0, 1200), lang: 'en', format: 'mp3' }, spoken_text: text } }];

// One memory row so the rest of JARVIS (screen, Telegram) knows what the research report contained.
let top = [];
try { top = $('Shortlist').first().json.top || []; } catch (e) { top = []; }
const plan = $('Research plan').first().json;
const day = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Toronto' });
const list = top.map((p, i) => `${i + 1}. ${p.name.split(/[-,|]/)[0].trim().slice(0, 60)} (CJ SKU ${p.sku || p.pid}, est. profit ${p.est_profit_cad} CAD, ${p.listed_by_stores} stores, competition ${p.competition}${p.meets_target ? ', meets targets' : ''})`).join('; ');
const summary = `Product research report sent to the owner's Telegram on ${day} (themes: ${plan.keywords.join(', ')}), with photos and a voice message. ` +
  (top.length ? `Products: ${list}. Estimates only; nothing ordered.` : 'No product passed the filters.');
return [{ json: { kind: 'research', summary: summary.slice(0, 1500) } }];
